    "data": [
        {
            "id": "101",
            "type": "dataset",
            "attributes": {
                "title": "Dane meteorologiczne",
                "category": "Environment",
                "resources_count": 5
            }
        },
        {
            "id": "202",
            "type": "dataset",
            "attributes": {
                "title": "Budżety gmin",
                "category": "Finance",
                "resources_count": 12
            }
        },
        {
